'use strict';

const { runPy } = require('../helper');

function detections(cameraId,
  {
    start,
    end = Date.now(),
    step = 30,
    ...rest
  } = {},
  srcDir = './data'
) {
  const id = Array.isArray(cameraId) ? cameraId.join(',') : cameraId;

  return runPy('detect_count.py', {
    args: [
      '-id', id,
      '-data', srcDir,
      '-s', start,
      '-e', end,
      '-step', step,
    ],
    ...rest,
  })
}

module.exports = detections;
